INSERT INTO principality (principality_id, principality_name, principality_summary, principality_status, image_key, video_key, founding_date, land_coefficient, created_at, published_at, created_by) VALUES
  (1, 'Киевское княжество', 'Стольный град Киев - крупнейший укреплённый центр Древней Руси. Город Владимира, город Ярослава и город Изяслава вместе с Подолом дают около 300 гектаров укреплённой площади, что делает Киев верхней границей шкалы при любой оценке городского населения домонгольской Руси.', 'published', 'kiev.jpg', 'kiev.mp4', '0882-01-01', 0.55, '2026-09-01 10:00:00', '2026-09-01 10:30:00', 1),
  (2, 'Черниговское княжество', 'Чернигов на Десне - второй по площади город Южной Руси: детинец, окольный город и Третьяк вместе занимают около 160 гектаров. Спасо-Преображенский собор 1030-х годов - старейший сохранившийся храм Руси.', 'published', 'chernigov.jpg', 'chernigov.mp4', '1024-01-01', 0.55, '2026-09-01 10:05:00', '2026-09-01 10:35:00', 1),
  (3, 'Псковская земля', 'Псков при слиянии Псковы и Великой - Кром, Довмонтов город и посады внутри крепостных стен дают около 150 гектаров. Каменные укрепления XIV-XVI веков сохранились почти полностью.', 'published', 'pskov.jpg', 'pskov.mp4', '0903-01-01', 0.55, '2026-09-01 10:10:00', '2026-09-01 10:40:00', 2),
  (4, 'Владимиро-Суздальское княжество', 'Владимир-на-Клязьме при Андрее Боголюбском вырос до 145 гектаров: Печерний город, Новый город и Ветчаной город с валами и Золотыми воротами. Столица Северо-Восточной Руси, застройка усадебная и плотная.', 'published', 'vladimir.jpg', 'vladimir.mp4', '1157-01-01', 0.55, '2026-09-01 10:15:00', '2026-09-01 10:45:00', 2),
  (5, 'Смоленское княжество', 'Смоленск занимал около 100 гектаров на днепровских холмах. Ключевой пункт пути из варяг в греки, с развитым ремесленным посадом и десятками каменных храмов домонгольской постройки.', 'published', 'smolensk.jpg', 'smolensk.mp4', '1054-01-01', 0.55, '2026-09-01 10:20:00', '2026-09-01 10:50:00', 3),
  (6, 'Переславль-Залесское княжество', 'Переславль-Залесский основан Юрием Долгоруким в 1152 году: земляной вал длиной около двух с половиной километров охватывает примерно 40 гектаров. Валы сохранились по всему периметру, поэтому площадь измеряется не по реконструкции, а по существующему укреплению.', 'published', 'pereslavl_zalessky.jpg', 'pereslavl_zalessky.mp4', '1152-01-01', 0.30, '2026-09-01 10:25:00', '2026-09-01 10:55:00', 3),
  (7, 'Переяславское княжество', 'Переяславль Южный на Трубеже - около 80 гектаров. Третий стол Русской земли наряду с Киевом и Черниговом, но постоянные половецкие набеги держали застройку менее плотной, чем в глубине страны.', 'published', 'pereyaslavl.jpg', 'pereyaslavl.mp4', '1054-01-01', 0.45, '2026-09-01 10:30:00', '2026-09-01 11:00:00', 1),
  (8, 'Полоцкое княжество', 'Полоцк на Западной Двине - около 58 гектаров. Древнейший центр кривичей, рано обособившийся от Киева; Софийский собор и детинец на высоком берегу задают компактную планировку.', 'published', 'polotsk.jpg', 'polotsk.mp4', '0988-01-01', 0.45, '2026-09-01 10:35:00', '2026-09-01 11:05:00', 4),
  (9, 'Галицкое княжество', '', 'draft', 'galich.jpg', 'galich.mp4', NULL, NULL, '2026-09-01 10:40:00', NULL, 2),
  (10, 'Муромо-Рязанское княжество', 'Старая Рязань на Оке - около 53 гектаров. Столица княжества, разорённая в 1237 году и после этого не восстановленная, поэтому её планировка изучена археологически лучше многих действующих городов.', 'removed', 'ryazan.jpg', 'ryazan.mp4', '1097-01-01', 0.45, '2026-09-01 10:45:00', '2026-09-01 11:10:00', 5);
